<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { t, locale, formatDate, formatNumber } from '../i18n'
import { Button } from '../components/ui/button'
import { useSettingsScope } from '../components/settingsScope'
import { dashboardMembers, dashboardPercent, dashboardTrend, validDashboard, type DashboardMemberMetric, type ProjectDashboard, type ProjectHealthReasonKey, type ProjectHealthStatus } from '../dashboard'

const scope=useSettingsScope(),days=ref(30),report=ref<ProjectDashboard|null>(null),loading=ref(false),error=ref(''),memberSearch=ref(''),memberSort=ref<DashboardMemberMetric|'name'>('requirementCount'),descending=ref(true),series=ref<'both'|'requirements'|'defects'>('both'),statusType=ref<'requirements'|'defects'>('requirements')
let sequence=0,disposed=false
const memberRows=computed(()=>dashboardMembers(report.value?.members||[],memberSearch.value,memberSort.value,descending.value,locale.value))
const trend=computed(()=>dashboardTrend(report.value?.trend||[],series.value))
const distribution=computed(()=>(report.value?.statuses[statusType.value]||[]).filter(status=>status.count>0))
const distributionTotal=computed(()=>report.value?.totals[statusType.value].total||0)
const executed=computed(()=>report.value?report.value.totals.executions.passed+report.value.totals.executions.failed+report.value.totals.executions.blocked:0)
const memberMetrics:{key:DashboardMemberMetric;label:string}[]=[{key:'requirementCount',label:'参与需求'},{key:'defectCount',label:'参与缺陷'},{key:'executionCount',label:'分配测试执行'}]
const weight=(value:number)=>formatNumber(value,{maximumFractionDigits:6})
function healthStatusText(status:ProjectHealthStatus){switch(status){case'healthy':return t('健康');case'at_risk':return t('需关注');case'blocked':return t('存在阻塞')}}
function healthStatusSummary(status:ProjectHealthStatus){switch(status){case'healthy':return t('当前没有发现延期或未关闭高严重度缺陷。');case'at_risk':return t('发现需要及时处理的交付风险。');case'blocked':return t('存在可能阻塞交付的致命缺陷。')}}
function healthReasonText(key:ProjectHealthReasonKey,count:number){switch(key){case'open_fatal_defects':return t('存在 {count} 个未关闭致命缺陷',{count});case'overdue_sprints':return t('{count} 个进行中迭代已过期',{count});case'overdue_requirements':return t('{count} 条未完成需求已逾期',{count});case'open_major_defects':return t('存在 {count} 个未关闭严重缺陷',{count})}}
function healthReasonTarget(key:ProjectHealthReasonKey){return key==='overdue_sprints'?'/iterations':key==='overdue_requirements'?'/requirements':'/defects'}
function invalidate(){sequence++;report.value=null;loading.value=false;error.value=''}
async function load(){
  if(disposed||!scope.current())return
  const version=++sequence,range=days.value;loading.value=true;error.value='';report.value=null
  try{const result=await scope.request<unknown>('/dashboard?days='+range);if(disposed||version!==sequence||!scope.current()||range!==days.value)return;if(!validDashboard(result,scope.project,range))throw new Error(t('统计上下文校验失败，请重试'));report.value=result}
  catch(cause){if(!disposed&&version===sequence&&scope.current())error.value=cause instanceof Error?cause.message:t('项目仪表盘暂时无法读取，请稍后重试')}
  finally{if(!disposed&&version===sequence&&scope.current())loading.value=false}
}
function sortMembers(key:DashboardMemberMetric|'name'){if(memberSort.value===key)descending.value=!descending.value;else{memberSort.value=key;descending.value=key!=='name'}}
watch(days,()=>{void load()});watch(scope.locked,locked=>{if(locked)invalidate()})
onMounted(()=>{void load()});onBeforeUnmount(()=>{disposed=true;invalidate()})
</script>

<template>
  <div class="dashboard-page" tabindex="0" role="region" :aria-label="t('项目仪表盘')">
    <header class="dashboard-heading compact-page-heading"><div><h1>{{report?.project.name||t('项目进展总览')}}</h1><details class="page-heading-note"><summary :aria-label="t('页面说明')" :title="t('页面说明')"><span aria-hidden="true">?</span></summary><p>{{t('需求、迭代与质量协作的实时全景。')}}</p></details></div><Button variant="outline" :disabled="loading||scope.locked.value" @click="load">{{t('刷新统计')}}</Button></header>
    <p v-if="error" class="dashboard-error" role="alert">{{t(error)}} <Button size="sm" variant="outline" :disabled="scope.locked.value" @click="load">{{t('重试')}}</Button></p>
    <div v-if="scope.locked.value" class="dashboard-empty" role="status">{{t('项目或账号已变化，请刷新页面后继续')}}</div>
    <div v-else-if="loading" class="dashboard-empty" role="status"><span class="spinner"></span>{{t('正在计算项目统计…')}}</div>
    <template v-if="report">
      <div class="dashboard-snapshot"><span>{{t('当前项目 · 全量数据')}}</span><small>{{t('当前状态快照')}} · {{formatDate(report.generatedAt)}}</small></div>
      <section class="dashboard-kpis" :aria-label="t('项目核心指标')">
        <router-link class="dashboard-kpi" to="/requirements"><span>{{t('需求总量')}}</span><strong>{{formatNumber(report.totals.requirements.total)}}</strong><div class="dashboard-meter"><i :style="{width:dashboardPercent(report.totals.requirements.done,report.totals.requirements.total)+'%'}"></i></div><small>{{t('已完成 {done} / 已取消 {cancelled}',{done:report.totals.requirements.done,cancelled:report.totals.requirements.cancelled})}}</small></router-link>
        <router-link class="dashboard-kpi" to="/defects"><span>{{t('未关闭缺陷')}}</span><strong>{{formatNumber(report.totals.defects.open)}}</strong><small>{{t('高严重度 {critical} · 总计 {total}',{critical:report.totals.defects.critical,total:report.totals.defects.total})}}</small><small>{{t('已关闭 {count}',{count:report.totals.defects.closed})}}</small></router-link>
        <router-link class="dashboard-kpi" to="/iterations"><span>{{t('进行中迭代')}}</span><strong>{{formatNumber(report.totals.sprints.ongoing)}}</strong><small>{{t('规划中 {planned} · 已完成 {done}',{planned:report.totals.sprints.planned,done:report.totals.sprints.completed})}}</small><small>{{t('共 {count} 个迭代',{count:report.totals.sprints.total})}}</small></router-link>
        <router-link class="dashboard-kpi" to="/tests?tab=cases"><span>{{t('测试用例')}}</span><strong>{{formatNumber(report.totals.testCases.total)}}</strong><small>{{t('启用 {count} 条用例',{count:report.totals.testCases.enabled})}}</small><small>{{t('{count} 个测试计划',{count:report.totals.testPlans.total})}}</small></router-link>
      </section>
      <section class="dashboard-health-panel" :class="'health-'+report.health.status" :aria-label="t('项目健康度')">
        <div class="dashboard-health-summary"><span>{{t('项目健康度')}}</span><strong>{{healthStatusText(report.health.status)}}</strong><p>{{healthStatusSummary(report.health.status)}}</p></div>
        <div class="dashboard-health-reasons"><router-link v-for="reason in report.health.reasons" :key="reason.key" :to="healthReasonTarget(reason.key)" class="dashboard-health-reason"><span>{{healthReasonText(reason.key,reason.count)}}</span><b aria-hidden="true">→</b></router-link><p v-if="!report.health.reasons.length" class="dashboard-health-clear">{{t('没有待处理的延期或高严重度缺陷。')}}</p></div>
        <footer>{{t('口径：未完成需求的计划结束日、进行中迭代结束日，以及未关闭的致命/严重缺陷。')}}</footer>
      </section>
      <section class="dashboard-grid">
        <article class="dashboard-panel dashboard-trend"><header><div><h2>{{t('真实新增趋势')}}</h2><p>{{t('按创建日期统计，不代表历史剩余工作量。')}}</p></div><select v-model.number="days" :aria-label="t('新增趋势时间范围')"><option :value="7">{{t('最近 7 天')}}</option><option :value="30">{{t('最近 30 天')}}</option><option :value="90">{{t('最近 90 天')}}</option></select></header>
          <div class="dashboard-chart-controls"><div><span class="dashboard-dot requirement"></span>{{t('新增需求')}} <b>{{formatNumber(trend.requirementTotal)}}</b></div><div><span class="dashboard-dot defect"></span>{{t('新增缺陷')}} <b>{{formatNumber(trend.defectTotal)}}</b></div><select v-model="series" :aria-label="t('趋势显示内容')"><option value="both">{{t('需求与缺陷')}}</option><option value="requirements">{{t('仅需求')}}</option><option value="defects">{{t('仅缺陷')}}</option></select></div>
          <template v-if="report.trendAvailable"><div class="dashboard-chart"><span class="dashboard-chart-maximum">{{formatNumber(trend.maximum)}}</span><svg viewBox="0 0 640 155" role="img" :aria-label="t('每日新增需求与缺陷趋势')"><line x1="0" x2="640" y1="16" y2="16" class="dashboard-grid-line"/><line x1="0" x2="640" y1="78" y2="78" class="dashboard-grid-line"/><line x1="0" x2="640" y1="140" y2="140" class="dashboard-grid-line"/><polyline v-if="series!=='defects'" :points="trend.requirements" class="dashboard-line requirement"/><polyline v-if="series!=='requirements'" :points="trend.defects" class="dashboard-line defect"/></svg><div class="dashboard-chart-dates"><span>{{formatDate(report.trend[0]?.date)}}</span><span>{{formatDate(report.trend.at(-1)?.date)}}</span></div></div><details class="dashboard-trend-details"><summary>{{t('查看每日准确数值')}}</summary><div class="dashboard-table-scroll" tabindex="0" :aria-label="t('每日新增明细')"><table><thead><tr><th>{{t('日期')}}</th><th>{{t('新增需求')}}</th><th>{{t('新增缺陷')}}</th></tr></thead><tbody><tr v-for="day in report.trend" :key="day.date"><td>{{formatDate(day.date)}}</td><td>{{formatNumber(day.requirementsCreated)}}</td><td>{{formatNumber(day.defectsCreated)}}</td></tr></tbody></table></div></details></template>
          <div v-else class="dashboard-empty">{{t('尚无可用的创建时间记录，暂不生成趋势图。')}}</div><p class="dashboard-note">{{t('日历时区：Asia/Shanghai；仅时间范围影响此趋势。')}}<span v-if="report.missingCreationDates"> {{t('{count} 条记录缺少有效创建日期，未计入趋势。',{count:report.missingCreationDates})}}</span></p>
        </article>
        <article class="dashboard-panel"><header><div><h2>{{t('工作项状态分布')}}</h2><p>{{t('按当前实际状态统计')}}</p></div><select v-model="statusType" :aria-label="t('状态分布类型')"><option value="requirements">{{t('需求')}}</option><option value="defects">{{t('缺陷')}}</option></select></header><div v-if="!distribution.length" class="dashboard-empty">{{t('暂无工作项')}}</div><div v-else class="dashboard-status-list"><div v-for="status in distribution" :key="status.key" class="dashboard-status-row"><div><span>{{status.system?t(status.name):status.name}}</span><b>{{formatNumber(status.count)}}</b></div><div class="dashboard-meter"><i :style="{width:dashboardPercent(status.count,distributionTotal)+'%'}"></i></div></div></div></article>
      </section>
      <section class="dashboard-grid dashboard-quality-grid"><article class="dashboard-panel"><header><div><h2>{{t('当前迭代')}}</h2><p>{{t('正在进行的迭代及其实际交付进度')}}</p></div><router-link to="/iterations">{{t('查看全部')}}</router-link></header><div v-if="!report.currentSprints.length" class="dashboard-empty">{{t('当前没有进行中的迭代，可在迭代池中规划并启动。')}}</div><div v-else class="dashboard-sprints"><router-link v-for="sprint in report.currentSprints" :key="sprint.id" :to="{path:'/iterations',query:{sprint:sprint.id}}" class="dashboard-sprint"><div><b>{{sprint.name}}</b><span>{{dashboardPercent(sprint.done,sprint.total)}}%</span></div><small>{{formatDate(sprint.startDate)}} — {{formatDate(sprint.endDate)}}</small><div class="dashboard-meter"><i :style="{width:dashboardPercent(sprint.done,sprint.total)+'%'}"></i></div><footer><span>{{t('完成 {done} / {total} 个工作项',{done:sprint.done,total:sprint.total})}}</span><span>{{t('需求权重 {value}',{value:weight(sprint.weightTotal)})}}</span></footer></router-link></div></article>
        <article class="dashboard-panel"><header><div><h2>{{t('测试执行概况')}}</h2><p>{{t('当前测试计划中的有效执行记录')}}</p></div><router-link to="/tests?tab=executions">{{t('查看执行')}}</router-link></header><div class="dashboard-quality-score"><strong>{{executed?dashboardPercent(report.totals.executions.passed,executed)+'%':'—'}}</strong><div><b>{{t('已执行通过率')}}</b><small>{{t('{done} / {total} 条已执行通过',{done:report.totals.executions.passed,total:executed})}}</small></div></div><div class="dashboard-test-counts"><div><span>{{t('通过')}}</span><b>{{formatNumber(report.totals.executions.passed)}}</b></div><div><span>{{t('失败')}}</span><b>{{formatNumber(report.totals.executions.failed)}}</b></div><div><span>{{t('阻塞')}}</span><b>{{formatNumber(report.totals.executions.blocked)}}</b></div><div><span>{{t('未执行')}}</span><b>{{formatNumber(report.totals.executions.notRun)}}</b></div></div><p class="dashboard-note">{{t('跳过 {count} 条执行，不计入通过率分母。',{count:report.totals.executions.skipped})}} {{t('通过率 = 通过 ÷（通过 + 失败 + 阻塞），未执行不计入分母。')}}</p></article></section>
      <section class="dashboard-panel dashboard-member-panel"><header><div><h2>{{t('成员协作分布')}}</h2><p>{{t('同一成员在同一工作项的多个角色只计一次。')}}</p></div><input v-model="memberSearch" :aria-label="t('搜索参与成员')" :placeholder="t('按成员姓名搜索')"/></header><div class="dashboard-table-scroll" tabindex="0" :aria-label="t('成员协作统计')"><table><thead><tr><th :aria-sort="memberSort==='name'?(descending?'descending':'ascending'):'none'"><button type="button" @click="sortMembers('name')">{{t('成员')}} {{memberSort==='name'?(descending?'↓':'↑'):'↕'}}</button></th><th v-for="metric in memberMetrics" :key="metric.key" :aria-sort="memberSort===metric.key?(descending?'descending':'ascending'):'none'"><button type="button" @click="sortMembers(metric.key)">{{t(metric.label)}} {{memberSort===metric.key?(descending?'↓':'↑'):'↕'}}</button></th></tr></thead><tbody><tr v-for="member in memberRows" :key="member.id"><td><span class="dashboard-avatar">{{member.name.slice(0,1)}}</span><b>{{member.name}}</b><small v-if="!member.active">{{t('历史停用成员')}}</small></td><td>{{formatNumber(member.requirementCount)}}</td><td>{{formatNumber(member.defectCount)}}</td><td>{{formatNumber(member.executionCount)}}</td></tr></tbody></table><div v-if="!memberRows.length" class="dashboard-empty">{{t('暂无匹配成员')}}</div></div><footer class="dashboard-note">{{t('成员参与数量允许跨成员重叠，不能直接相加作为项目总量。')}} {{t('统计不等同于个人绩效或缺陷责任。')}}</footer></section>
      <details class="dashboard-definitions"><summary>{{t('统计口径与使用说明')}}</summary><ul><li>{{t('所有总量来自当前授权项目的完整数据，不受列表分页、趋势时间或成员搜索影响。')}}</li><li>{{t('需求仅 done 类别计为完成；取消不算完成。缺陷仅已关闭计为完成，已拒绝不计入未关闭缺陷。')}}</li><li>{{t('高严重度缺陷指尚未关闭且严重度为致命或严重的缺陷。')}}</li><li>{{t('迭代进度按需求和缺陷 ID 分别计数；父子需求只贡献自身一次，需求权重不包含工时。')}}</li><li>{{t('需求成员包含处理人、负责人和五职能绑定人；缺陷包含处理人与验证人；测试按执行人归属，仅使用稳定成员 ID。')}}</li><li>{{t('状态分布和成员关系是当前快照，没有历史剩余工作量快照时不展示燃尽曲线。')}}</li></ul></details>
    </template>
  </div>
</template>

<style scoped>
